import sys

class TextDocumentAnalysis:
    @staticmethod
    def input(s):
        length = len(s)
        inParen = False
        totalWords = 0
        maxWordSize = 0
        currentSize = 0
        for i in range(length):
            c = s[i]
            if c == '(':
                if currentSize > 0:
                    if currentSize > maxWordSize:
                        maxWordSize = currentSize
                    currentSize = 0
                inParen = True
            elif c == ')':
                if currentSize > 0:
                    totalWords += 1
                    currentSize = 0
                inParen = False
            elif c == '_':
                if currentSize > 0:
                    if inParen:
                        totalWords += 1
                    else:
                        if currentSize > maxWordSize:
                            maxWordSize = currentSize
                    currentSize = 0
            else:
                currentSize += 1
        if currentSize > 0:
            if inParen:
                totalWords += 1
            else:
                if currentSize > maxWordSize:
                    maxWordSize = currentSize
        return str(maxWordSize) + " " + str(totalWords)

def main():
    for line in sys.stdin:
        line = line.rstrip('\n')
        if line:
            print(TextDocumentAnalysis.input(line))

if __name__ == "__main__":
    main()

